import math

class Solution:
    def isGoodArray(self, nums: list[int]) -> bool:
        g = nums[0]
        for x in nums:
            g = math.gcd(g, x)
            if g == 1:
                return True
        return g == 1

class Solution {
    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
public:
    bool isGoodArray(std::vector<int>& nums) {
        int g = nums[0];
        for (int x : nums) {
            g = gcd(g, x);
            if (g == 1) return true;
        }
        return g == 1;
    }
};

class Solution {
    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    public boolean isGoodArray(int[] nums) {
        int g = nums[0];
        for (int x : nums) {
            g = gcd(g, x);
            if (g == 1) return true;
        }
        return g == 1;
    }
}

var isGoodArray = function(nums) {
    const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
    let g = nums[0];
    for (const x of nums) {
        g = gcd(g, x);
        if (g === 1) return true;
    }
    return g === 1;
};
